from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,subprocess
root=Path('/Users/alexy/src/sail-extensions-gates/stream-experiments-20260930')
config=root/'logging03-compact.json'
assert hashlib.sha256(config.read_bytes()).hexdigest()=='b28132996612b11edb77bb02019288e4a562db5e4d22c4430a6a8815a220aea0'
r={'started_utc':datetime.now(timezone.utc).isoformat(),'files':{},'commands':{}}
for name in ['result.json','collection.json','cell/orchestration.json','diagnostics/receipt.json']:
 p=root/'logging03-compact'/name
 r['files'][name]={'exists':p.exists()}
 if p.is_file():
  data=p.read_bytes();r['files'][name].update(bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),value=json.loads(data))
commands=[('container',['/usr/local/bin/docker','--context','colima-sail-gate','inspect','--format','{{json .State}}','sail-stream-log03-compact-1']),('supervisor_pids',['/usr/bin/pgrep','-f',r'run_focused_safe[.]py /Users/alexy/src/sail-extensions-gates/stream-experiments-20260930/logging03-compact[.]json$'])]
for label,cmd in commands:
 p=subprocess.run(cmd,text=True,capture_output=True,timeout=8);r['commands'][label]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
pids=r['commands']['supervisor_pids']['stdout'].split()
if pids and all(p.isdigit()for p in pids):
 p=subprocess.run(['/bin/ps','-p',','.join(pids),'-o','pid=,ppid=,comm='],text=True,capture_output=True,timeout=5);r['commands']['supervisor_identity']={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
r['finished_utc']=datetime.now(timezone.utc).isoformat();print(json.dumps(r))
